function Get-ConsumersLocalPins {$p=[ordered]@{};foreach($n in @('consumers-localreadonly21-v2.ps1','consumers-localreadonly21.mjs','consumer-meta-readonly-v2-20261021.ps1','phase10-independent-incident-inventory.ps1','incident-common.ps1','scheduler-live-helpers.ps1')){$p[$n]=(Get-FileHash -LiteralPath (Join-Path $PSScriptRoot $n) -Algorithm SHA256).Hash.ToLowerInvariant()};return $p}
function Get-ConsumersSharedMaterial($Variables,[string]$Mcp,[string]$Inspector){
 if($Variables.SUPABASE_DATABASE_PROJECT_REF -cne 'ehnfrrmbkvlsbpvqcvkr' -or $Variables.SUPABASE_DATABASE_SCHEMA -cne 'phase08_meta_ads'){throw 'BASELINE_SCOPE'}
 $encoded=[string]$Variables.PHASE08_GOOGLE_ADC_JSON_B64;if($encoded.Length -lt 32 -or $encoded.Length -gt 2097152){throw 'ADC_BOUND'};$adcBytes=$null;$adc=$null
 try{$adcBytes=[Convert]::FromBase64String($encoded);$adc=[Text.UTF8Encoding]::new($false,$true).GetString($adcBytes)|ConvertFrom-Json -AsHashtable -Depth 20 -DateKind String;if($adc.type -cne 'impersonated_service_account' -or $adc.source_credentials.type -cne 'authorized_user'){throw 'ADC_TYPE'}
 $material=[ordered]@{SUPABASE=@{literals=@([string]$Variables.SUPABASE_SECRET_KEY);encoded=@()};CAFE=@{literals=@([string]$Variables.DAILY_SYNC_CAFE24_CLIENT_SECRET);encoded=@()};GOOGLE=@{literals=@([string]$adc.source_credentials.client_secret,[string]$adc.source_credentials.refresh_token);encoded=@($encoded)};META=@{literals=@($Mcp,$Inspector,[string]$Variables.DAILY_SYNC_META_VAULT_KEY);encoded=@([string]$Variables.PHASE08_META_RECORD_B64)}}
 foreach($class in $material.Keys){foreach($value in @($material[$class].literals)+@($material[$class].encoded)){if($value.Length -lt 8 -or $value.Length -gt 524288){throw 'MATERIAL_BOUND'}}};return $material
 }finally{if($adcBytes){[Array]::Clear($adcBytes,0,$adcBytes.Length)};$adc=$null;$encoded=$null}
}
if($MyInvocation.InvocationName -ceq '.'){return}
$stage='INITIALIZE';$baseline=$null;$material=$null;$mcp=$null;$inspector=$null;$wire=$null;$output=$null;$process=$null;$secrets=[Collections.Generic.List[string]]::new()
try{
 $pins=Get-ConsumersLocalPins;if(-not $Execute){@{kind='ALL_SHARED_LOCAL_CONSUMER_SCAN_TOOL';status='READY_NOT_EXECUTED';pins=$pins;protectedReads=0;remoteRequests=0;remoteWrites=0}|ConvertTo-Json -Depth 5 -Compress;exit 0}
 $stage='ATTEMPT';$null=Write-MetaConsumerNew @{kind='LOCAL_ALL4_ATTEMPT';startedAt=[DateTimeOffset]::UtcNow.ToString('o');pins=$pins;remoteRequests=0;remoteWrites=0} 'attempt.json'
 $stage='BASELINE';$baseline=Read-IncidentPrivate 'compromised-baseline';$stage='MCP_TOKEN';$mcp=Read-IndependentIncidentMetaToken 'mcp-access-token.dpapi';$stage='INSPECTOR_TOKEN';$inspector=Read-IndependentIncidentMetaToken 'inspector-token.dpapi';$stage='MATERIAL';$material=Get-ConsumersSharedMaterial $baseline.variables $mcp $inspector
 foreach($class in $material.Keys){foreach($value in @($material[$class].literals)+@($material[$class].encoded)){[void]$secrets.Add($value)}}
 $stage='LOCAL_SCAN';$start=[Diagnostics.ProcessStartInfo]::new('node');$start.UseShellExecute=$false;$start.CreateNoWindow=$true;$start.RedirectStandardInput=$true;$start.RedirectStandardOutput=$true;$start.RedirectStandardError=$true;$start.StandardInputEncoding=[Text.UTF8Encoding]::new($false);$start.StandardOutputEncoding=[Text.UTF8Encoding]::new($false);$start.ArgumentList.Add((Join-Path $PSScriptRoot 'consumers-localreadonly21.mjs'));$start.Environment['CONSUMERS_LOCALREADONLY_PARENT']='20261021-ROOT';$process=[Diagnostics.Process]::new();$process.StartInfo=$start;if(-not $process.Start()){throw 'NODE_START'};$outTask=$process.StandardOutput.ReadToEndAsync();$errTask=$process.StandardError.ReadToEndAsync();$wire=@{material=$material}|ConvertTo-Json -Compress -Depth 12;$process.StandardInput.Write($wire);$process.StandardInput.Close();$wire=$null
 if(-not $process.WaitForExit(660000)){try{$process.Kill($true)}catch{};throw 'NODE_TIMEOUT'};$output=$outTask.GetAwaiter().GetResult();$null=$errTask.GetAwaiter().GetResult();if($process.ExitCode -ne 0 -or $output.Length -gt 4194304){throw 'NODE_RESULT'}
 $stage='PROJECTION';foreach($value in $secrets){if($output.Contains($value,[StringComparison]::Ordinal)){throw 'OUTPUT_SECRET'}};$result=$output|ConvertFrom-Json -AsHashtable -Depth 30 -DateKind String;if($result.kind -cne 'ALL_SHARED_LOCAL_CONSUMER_SCAN' -or $result.remoteRequests -ne 0 -or $result.remoteWrites -ne 0 -or $result.rawValuesReturned -ne 0){throw 'RESULT_SHAPE'};if((Get-IncidentHash $pins) -cne (Get-IncidentHash (Get-ConsumersLocalPins))){throw 'SOURCE_DRIFT'};$result.sourcePins=$pins;$result.protectedReadScope='HISTORICAL_COMPROMISED_BASELINE_AND_TWO_EXISTING_META_TOKEN_ARTIFACTS';$result.sharedCredentialsChanged=$false;$path=Write-MetaConsumerNew $result 'result.json';@{kind=$result.kind;status='LOCAL_READ_FINISHED_SUBSET_LIMITS_EXPLICIT';evidence=$path;files=$result.files;bytes=$result.bytes;matchFiles=@($result.records).Count;capReached=$result.capReached;remoteRequests=0;remoteWrites=0;rawValuesReturned=0}|ConvertTo-Json -Compress
}catch{$safe=Get-MetaConsumerFailureMetadata $_;$failure=@{kind='ALL_SHARED_LOCAL_CONSUMER_SCAN';status='SAFE_FAILURE';stage=$stage;diagnostic=$safe;rawErrorSuppressed=$true;rawValuesReturned=0;remoteRequests=0;remoteWrites=0};try{$null=Write-MetaConsumerNew $failure 'failure.json'}catch{};$failure|ConvertTo-Json -Compress;exit 1}
finally{if($process){try{if(-not $process.HasExited){$process.Kill($true)}}catch{};$process.Dispose()};$baseline=$null;$material=$null;$mcp=$null;$inspector=$null;$wire=$null;$output=$null;$secrets.Clear()}
